ALTER TABLE public.events ADD COLUMN IF NOT EXISTS live_followup_enabled boolean NOT NULL DEFAULT true;
CREATE TABLE public.live_followup_sources (source_key text PRIMARY KEY,event_id uuid NOT NULL,order_id uuid,access_id uuid,changed_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.live_followup_sources TO service_role;
ALTER TABLE public.live_followup_sources ENABLE ROW LEVEL SECURITY;
CREATE INDEX live_followup_sources_changed ON public.live_followup_sources(changed_at,source_key);
CREATE TABLE public.live_followup_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL,order_id uuid,access_id uuid,customer_key text NOT NULL,phone text,instagram text,whatsapp_number_id uuid,channel text NOT NULL,type text NOT NULL,step integer NOT NULL,sequence_key text NOT NULL,variant integer,message text,scheduled_at timestamptz NOT NULL,base_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending',reason text,claimed_at timestamptz,sent_at timestamptz,message_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_key,sequence_key,step),CONSTRAINT live_followup_job_status CHECK(status IN ('pending','processing','sent','skipped','cancelled','uncertain')));
GRANT SELECT ON public.live_followup_jobs TO authenticated;
GRANT ALL ON public.live_followup_jobs TO service_role;
ALTER TABLE public.live_followup_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY live_followup_staff_read ON public.live_followup_jobs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_module_access(auth.uid(),'events'));
CREATE INDEX live_followup_jobs_due ON public.live_followup_jobs(scheduled_at,id) WHERE status='pending';
CREATE INDEX live_followup_jobs_instance_history ON public.live_followup_jobs(whatsapp_number_id,claimed_at DESC) WHERE claimed_at IS NOT NULL;
CREATE INDEX live_followup_jobs_customer_history ON public.live_followup_jobs(customer_key,claimed_at DESC) WHERE claimed_at IS NOT NULL;
CREATE INDEX live_followup_jobs_sequence ON public.live_followup_jobs(sequence_key,step);
CREATE INDEX live_followup_jobs_event_history ON public.live_followup_jobs(event_id,created_at DESC,id);
CREATE INDEX live_followup_jobs_history ON public.live_followup_jobs(created_at DESC,id);
CREATE INDEX live_followup_jobs_order ON public.live_followup_jobs(order_id,status);
CREATE TABLE public.live_followup_instances (whatsapp_number_id uuid PRIMARY KEY,next_send_at timestamptz NOT NULL DEFAULT now(),paused boolean NOT NULL DEFAULT false,reason text,consecutive_errors integer NOT NULL DEFAULT 0,last_message text);
GRANT SELECT ON public.live_followup_instances TO authenticated;
GRANT ALL ON public.live_followup_instances TO service_role;
ALTER TABLE public.live_followup_instances ENABLE ROW LEVEL SECURITY;
CREATE POLICY live_followup_instances_staff ON public.live_followup_instances FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_module_access(auth.uid(),'events'));
CREATE TABLE public.live_followup_daily (day date NOT NULL,event_id uuid NOT NULL,sent integer NOT NULL DEFAULT 0,skipped integer NOT NULL DEFAULT 0,paid integer NOT NULL DEFAULT 0,PRIMARY KEY(day,event_id));
GRANT SELECT ON public.live_followup_daily TO authenticated;
GRANT ALL ON public.live_followup_daily TO service_role;
ALTER TABLE public.live_followup_daily ENABLE ROW LEVEL SECURITY;
CREATE POLICY live_followup_daily_staff ON public.live_followup_daily FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_module_access(auth.uid(),'events'));
CREATE OR REPLACE FUNCTION public.live_followup_enabled(p_event_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT (value->>'enabled')::boolean FROM app_settings WHERE key='live_followup_global'),false) AND (p_event_id IS NULL OR coalesce((SELECT live_followup_enabled FROM events WHERE id=p_event_id),false)) $$;
REVOKE ALL ON FUNCTION public.live_followup_enabled(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_enabled(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_dirty() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_key text; BEGIN IF NOT public.live_followup_enabled(NEW.event_id) THEN RETURN NEW; END IF; v_key:=TG_TABLE_NAME||':'||NEW.id; INSERT INTO live_followup_sources(source_key,event_id,order_id,access_id,changed_at) VALUES(v_key,NEW.event_id,CASE WHEN TG_TABLE_NAME='orders' THEN NEW.id END,CASE WHEN TG_TABLE_NAME='live_selfservice_accesses' THEN NEW.id END,clock_timestamp()) ON CONFLICT(source_key) DO UPDATE SET changed_at=excluded.changed_at; RETURN NEW; EXCEPTION WHEN others THEN RAISE WARNING '[live-followup-dirty] %',SQLERRM; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.live_followup_dirty() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_dirty() TO service_role;
CREATE TRIGGER live_followup_order_insert AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.live_followup_dirty();
CREATE TRIGGER live_followup_order_update AFTER UPDATE ON public.orders FOR EACH ROW WHEN (OLD.products IS DISTINCT FROM NEW.products OR OLD.registered_at IS DISTINCT FROM NEW.registered_at OR OLD.selfservice_cart_sent_at IS DISTINCT FROM NEW.selfservice_cart_sent_at OR OLD.last_sent_message_at IS DISTINCT FROM NEW.last_sent_message_at OR OLD.is_paid IS DISTINCT FROM NEW.is_paid OR OLD.paid_externally IS DISTINCT FROM NEW.paid_externally OR OLD.stage IS DISTINCT FROM NEW.stage OR OLD.merged_into_order_id IS DISTINCT FROM NEW.merged_into_order_id) EXECUTE FUNCTION public.live_followup_dirty();
CREATE TRIGGER live_followup_access_insert AFTER INSERT ON public.live_selfservice_accesses FOR EACH ROW EXECUTE FUNCTION public.live_followup_dirty();
CREATE TRIGGER live_followup_access_update AFTER UPDATE ON public.live_selfservice_accesses FOR EACH ROW WHEN (OLD.entered_phone IS DISTINCT FROM NEW.entered_phone OR OLD.order_ids IS DISTINCT FROM NEW.order_ids OR OLD.registered_at IS DISTINCT FROM NEW.registered_at OR OLD.whatsapp_confirmed_at IS DISTINCT FROM NEW.whatsapp_confirmed_at) EXECUTE FUNCTION public.live_followup_dirty();
CREATE OR REPLACE FUNCTION public.live_followup_sources_claim(p_limit integer DEFAULT 50) RETURNS SETOF public.live_followup_sources LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ DELETE FROM live_followup_sources WHERE source_key IN (SELECT source_key FROM live_followup_sources ORDER BY changed_at,source_key LIMIT least(greatest(p_limit,1),100) FOR UPDATE SKIP LOCKED) RETURNING * $$;
REVOKE ALL ON FUNCTION public.live_followup_sources_claim(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_sources_claim(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_claim(p_limit integer DEFAULT 20) RETURNS SETOF public.live_followup_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE j live_followup_jobs; cfg jsonb; pacing live_followup_instances; v_hour integer; v_day integer; v_min integer; v_max integer; chosen integer; used integer[];
BEGIN SELECT value INTO cfg FROM app_settings WHERE key='live_followup_global'; IF NOT coalesce((cfg->>'enabled')::boolean,false) THEN UPDATE live_followup_jobs SET status='cancelled',reason='global_disabled' WHERE status='pending'; RETURN; END IF;
FOR j IN SELECT * FROM live_followup_jobs WHERE status='pending' AND scheduled_at<=now() ORDER BY scheduled_at,id LIMIT least(greatest(p_limit,1),50) FOR UPDATE SKIP LOCKED LOOP
IF NOT public.live_followup_enabled(j.event_id) THEN UPDATE live_followup_jobs SET status='cancelled',reason='event_disabled' WHERE id=j.id; CONTINUE; END IF;
IF j.whatsapp_number_id IS NULL THEN UPDATE live_followup_jobs SET status='skipped',reason='no_instance' WHERE id=j.id; CONTINUE; END IF;
INSERT INTO live_followup_instances(whatsapp_number_id) VALUES(j.whatsapp_number_id) ON CONFLICT DO NOTHING;
SELECT * INTO pacing FROM live_followup_instances WHERE whatsapp_number_id=j.whatsapp_number_id FOR UPDATE;
IF pacing.paused OR pacing.next_send_at>now() THEN CONTINUE; END IF;
IF EXISTS(SELECT 1 FROM live_followup_jobs WHERE whatsapp_number_id=j.whatsapp_number_id AND status IN ('processing','uncertain')) THEN CONTINUE; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(j.customer_key,72819));
SELECT count(*) INTO v_hour FROM live_followup_jobs WHERE whatsapp_number_id=j.whatsapp_number_id AND claimed_at>now()-interval '1 hour'; IF v_hour>=coalesce((cfg->'limits'->>'hourly')::integer,40) THEN CONTINUE; END IF;
SELECT count(*) INTO v_day FROM live_followup_jobs WHERE customer_key=j.customer_key AND claimed_at>=((now() AT TIME ZONE 'America/Sao_Paulo')::date::timestamp AT TIME ZONE 'America/Sao_Paulo'); IF v_day>=coalesce((cfg->'limits'->>'daily_customer')::integer,6) THEN UPDATE live_followup_jobs SET status='skipped',reason='customer_daily_limit' WHERE id=j.id; CONTINUE; END IF;
IF j.type='D' AND now()>j.scheduled_at+interval '15 minutes' THEN UPDATE live_followup_jobs SET status='skipped',reason='late_step' WHERE id=j.id; CONTINUE; END IF;
IF j.step>0 AND EXISTS(SELECT 1 FROM live_followup_jobs WHERE sequence_key=j.sequence_key AND step<j.step AND status IN ('pending','processing','uncertain')) THEN CONTINUE; END IF;
SELECT array_agg(variant) INTO used FROM live_followup_jobs WHERE customer_key=j.customer_key AND type=j.type AND step=j.step AND variant IS NOT NULL AND status IN ('sent','processing','uncertain'); SELECT x INTO chosen FROM generate_series(0,2) x WHERE NOT x=ANY(coalesce(used,'{}'::integer[])) ORDER BY random() LIMIT 1;
IF chosen IS NULL THEN UPDATE live_followup_jobs SET status='skipped',reason='variations_exhausted' WHERE id=j.id; CONTINUE; END IF;
v_min:=coalesce((cfg->'limits'->>'interval_min')::integer,20);v_max:=coalesce((cfg->'limits'->>'interval_max')::integer,60);
UPDATE live_followup_instances SET next_send_at=clock_timestamp()+make_interval(secs=>v_min+floor(random()*(v_max-v_min+1))::integer) WHERE whatsapp_number_id=j.whatsapp_number_id;
UPDATE live_followup_jobs SET status='processing',claimed_at=clock_timestamp(),variant=chosen WHERE id=j.id RETURNING * INTO j; RETURN NEXT j;
END LOOP; END $$;
REVOKE ALL ON FUNCTION public.live_followup_claim(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_claim(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_accounting() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('sent','skipped','cancelled') THEN INSERT INTO live_followup_daily(day,event_id,sent,skipped) VALUES((now() AT TIME ZONE 'America/Sao_Paulo')::date,NEW.event_id,CASE WHEN NEW.status='sent' THEN 1 ELSE 0 END,CASE WHEN NEW.status IN ('skipped','cancelled') THEN 1 ELSE 0 END) ON CONFLICT(day,event_id) DO UPDATE SET sent=live_followup_daily.sent+excluded.sent,skipped=live_followup_daily.skipped+excluded.skipped; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.live_followup_accounting() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_accounting() TO service_role;
CREATE TRIGGER live_followup_job_accounting AFTER UPDATE OF status ON public.live_followup_jobs FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status) EXECUTE FUNCTION public.live_followup_accounting();
CREATE OR REPLACE FUNCTION public.live_followup_paid() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(NEW.is_paid,false) OR coalesce(NEW.paid_externally,false) THEN IF EXISTS(SELECT 1 FROM live_followup_jobs WHERE order_id=NEW.id AND status='sent') THEN INSERT INTO live_followup_daily(day,event_id,paid) VALUES((now() AT TIME ZONE 'America/Sao_Paulo')::date,NEW.event_id,1) ON CONFLICT(day,event_id) DO UPDATE SET paid=live_followup_daily.paid+1; END IF; UPDATE live_followup_jobs SET status='cancelled',reason='paid' WHERE order_id=NEW.id AND status='pending'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.live_followup_paid() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_paid() TO service_role;
CREATE TRIGGER live_followup_order_paid AFTER UPDATE ON public.orders FOR EACH ROW WHEN ((NEW.is_paid OR NEW.paid_externally) AND NOT (OLD.is_paid OR OLD.paid_externally)) EXECUTE FUNCTION public.live_followup_paid();